    return results


def extract_result(event: StreamEvent) -> ResultEvent | None:
    """Extract result data from a 'result' event. Returns None if not a result."""
    if event.type != "result":
        return None
    raw = event.raw
    mu = raw.get("modelUsage") or {}
    model = next(iter(mu), "") if mu else raw.get("model", "")
    return ResultEvent(
        text=raw.get("result", ""),
        session_id=raw.get("session_id"),
        usage=raw.get("usage") or {},
        model_usage=mu,
        model=model,
        cost_usd=raw.get("total_cost_usd"),
    )


def find_result_in_output(output: str) -> ResultEvent | None:
    """Scan all lines for the best 'result' event.

    When multiple result events exist (e.g. background task_notification),
    prefers the one whose text contains structured JSON data.
    Falls back to the last result event.
    """
    last_result: ResultEvent | None = None
    json_result: ResultEvent | None = None
    for event in iter_stream_events(output.splitlines()):
        r = extract_result(event)
        if r is not None:
            last_result = r
            if json_result is None and extract_json_object(r.text):
                json_result = r
    return json_result if json_result is not None else last_result


def extract_last_assistant_text(output: str) -> str:
    """Fallback: get last assistant text block when no result event exists."""
    last_text = ""
    for event in iter_stream_events(output.splitlines()):
        if event.type == "assistant":
            msg = event.raw.get("message", {})
            for block in msg.get("content", []):
                if isinstance(block, dict) and block.get("type") == "text":
                    last_text = block.get("text", "")
    return last_text


